// -----------------------------------------------------------------------------
// Canvas and scaling
// -----------------------------------------------------------------------------

const W = 224;
const H = 288;
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resizeCanvas() {
  const sx = Math.floor(window.innerWidth / W);
  const sy = Math.floor(window.innerHeight / H);
  const scale = Math.max(1, Math.min(sx, sy));
  canvas.style.width = (W * scale) + "px";
  canvas.style.height = (H * scale) + "px";
  ctx.imageSmoothingEnabled = false;
}
window.addEventListener("resize", resizeCanvas);
resizeCanvas();

// -----------------------------------------------------------------------------
// Synthesized audio
// -----------------------------------------------------------------------------

const sfx = {
  ctx: null,
  muted: false,

  ensure() {
    if (!this.ctx) {
      try {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (AC) this.ctx = new AC();
      } catch (e) {
        this.ctx = null;
      }
    }
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume().catch(() => {});
    }
  },

  tone(freq, dur, type, vol, slideTo, delay) {
    if (!this.ctx || this.muted) return;
    this.ensure();
    if (!this.ctx) return;

    const t = this.ctx.currentTime + (delay || 0);
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = type || "square";
    osc.frequency.setValueAtTime(Math.max(1, freq), t);
    if (slideTo) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(1, slideTo), t + dur);
    }

    gain.gain.setValueAtTime(Math.max(0.0001, vol || 0.1), t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);

    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  },

  noise(dur, vol, filterFreq, delay) {
    if (!this.ctx || this.muted) return;
    this.ensure();
    if (!this.ctx) return;

    const t = this.ctx.currentTime + (delay || 0);
    const sampleRate = this.ctx.sampleRate || 44100;
    const len = Math.max(1, Math.floor(sampleRate * dur));
    const buffer = this.ctx.createBuffer(1, len, sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

    const src = this.ctx.createBufferSource();
    src.buffer = buffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = filterFreq || 1000;

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(Math.max(0.0001, vol || 0.1), t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);

    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.ctx.destination);

    src.start(t);
    src.stop(t + dur + 0.02);
  },

  shot() {
    this.tone(880, 0.08, "square", 0.035, 220);
  },

  enemyHit() {
    this.tone(220, 0.08, "square", 0.055, 110);
  },

  enemyDestroyed() {
    this.noise(0.18, 0.10, 1200);
    this.tone(120, 0.18, "sawtooth", 0.05, 60);
  },

  bossHit() {
    this.tone(300, 0.12, "square", 0.07, 600);
  },

  playerExplosion() {
    this.noise(0.45, 0.17, 900);
    this.tone(220, 0.45, "sawtooth", 0.08, 50);
  },

  tractor() {
    this.tone(180, 0.55, "sine", 0.045, 900);
    this.tone(220, 0.55, "sine", 0.03, 1100);
  },

  capture() {
    this.tone(700, 0.45, "square", 0.06, 120);
  },

  dock() {
    this.tone(420, 0.25, "square", 0.07, 1200);
    this.tone(630, 0.25, "square", 0.05, 1600, 0.08);
  },

  stageStart() {
    this.tone(523, 0.12, "square", 0.05, null, 0.00);
    this.tone(659, 0.12, "square", 0.05, null, 0.12);
    this.tone(784, 0.12, "square", 0.05, null, 0.24);
    this.tone(1047, 0.22, "square", 0.05, null, 0.36);
  },

  extraShip() {
    this.tone(1047, 0.10, "square", 0.05, null, 0.00);
    this.tone(1319, 0.10, "square", 0.05, null, 0.10);
    this.tone(1568, 0.18, "square", 0.05, null, 0.20);
  },

  gameOver() {
    this.tone(440, 0.18, "square", 0.06, null, 0.00);
    this.tone(330, 0.18, "square", 0.06, null, 0.18);
    this.tone(220, 0.22, "square", 0.06, null, 0.36);
    this.tone(110, 0.35, "square", 0.06, null, 0.55);
  }
};

// -----------------------------------------------------------------------------
// Pixel sprites
// -----------------------------------------------------------------------------

function makeSprite(rows, colorMap) {
  const h = rows.length;
  const w = rows[0].length;
  const c = document.createElement("canvas");
  c.width = w;
  c.height = h;
  const g = c.getContext("2d");

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < rows[y].length; x++) {
      const ch = rows[y][x];
      const col = colorMap[ch];
      if (col) {
        g.fillStyle = col;
        g.fillRect(x, y, 1, 1);
      }
    }
  }
  return c;
}

const ZAKO_F1 = [
